values ('fq_iron_094', 'Forge Final Production', 'hunt', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'The Forge enters final mass production. (Location: Prima Materia Forge, Foreman Brigg) Eliminate the last remaining threats to production.', '{"npc_id": "npc_assembly_foreman", "name": "Foreman Brigg", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 93, "reputation_required": 5520, "required_quests": ["fq_iron_093"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 8, "desc": "Eliminate production threats.", "description": "Defeat Aethel Void Channeler (x8)."}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Override final rogue Automatons.", "description": "Defeat Titan Forge Automaton (x3)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "raw_aethel_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_095', false, NULL, NULL, NULL, 'quest_iron.json', 93)
