values ('fq_iron_095', 'Expanse Conquest', 'hunt', 'S', 'IRON_HEGEMONY', 'CRADLE_EXPANSE', 'The Cradle Expanse is now Hegemony sovereign territory. Enforce it. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 94, "reputation_required": 5580, "required_quests": ["fq_iron_094"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 10, "desc": "Enforce sovereignty.", "description": "Defeat Aethel Rift Stalker (x10)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Destroy residual Titan presence.", "description": "Defeat Gravity Titan (x1)."}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_096', false, NULL, NULL, NULL, 'quest_iron.json', 94)
