values ('fq_iron_096', 'Orbital Command', 'hunt', 'S', 'IRON_HEGEMONY', 'ORBITAL_SENTINEL_COMMAND', 'From orbit, the Hegemony watches over our conquered world. (Location: Orbital Sentinel Command, Commander Drax) Maintain orbital supremacy forever.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 95, "reputation_required": 5640, "required_quests": ["fq_iron_095"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 10, "desc": "Patrol and clear orbital sectors.", "description": "Defeat Aethel Iron Carapace (x10)."}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Eliminate remaining Behemoths.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 3800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_iron_097', false, NULL, NULL, NULL, 'quest_iron.json', 95)
