values ('fq_iron_097', 'The Final Campaign', 'story', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'The Hegemony launches the Final Campaign to eliminate all significant threats. (Location: Prima Materia Forge, Commander Drax) Channel your command authority into the war effort.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 96, "reputation_required": 530, "required_quests": ["fq_iron_096"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Destroy Jotunn command units.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Destroy the Harbinger''s last echo.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "desc": "Confirm Final Campaign complete.", "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_098', false, NULL, NULL, NULL, 'quest_iron.json', 96)
