values ('fq_iron_098', 'The Final Conquest', 'story', 'S', 'IRON_HEGEMONY', 'PRIMA_MATERIA_FORGE', 'Only the ultimate conquest remains. (Location: Prima Materia Forge, Commander Drax) Face the three Apex entities — Jotunn, Drake, Harbinger. The Hegemony conquers all.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 97, "reputation_required": 580, "required_quests": ["fq_iron_097"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Conquer the Apex Jotunn.", "description": "Defeat Gigantic Jotunn (x1)."}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Conquer the Apex Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Conquer the Apex Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Claim the Conquest Seal.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 7000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "titan_core", "quantity": 3}, {"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_iron_099', false, NULL, NULL, NULL, 'quest_iron.json', 97)
