values ('fq_iron_099', 'Eternal Hegemon Trial', 'story', 'S', 'IRON_HEGEMONY', 'VOID_ECHO_CHASM', 'The deepest Void Echo Chasm holds the final test. Defeat the eternal forms of Titan and Harbinger in single combat. The Hegemony demands nothing less than total victory. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 630, "required_quests": ["fq_iron_098"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Descend to the deepest chasm.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Defeat the Eternal Gravity Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Destroy the Eternal Abyss Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "CLAIM THE ETERNAL HEGEMON SEAL.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_iron_100', false, NULL, NULL, NULL, 'quest_iron.json', 98)
