values ('fq_iron_100', 'Eternal Hegemon', 'story', 'SS', 'IRON_HEGEMONY', 'BASTION_CORE', 'You have conquered everything. (Location: Bastion Core, Commander Drax) Titan. Harbinger. Drake. All have fallen to Hegemony steel. Return to the Bastion as the ETERNAL HEGEMON. Your name will be forged into the Bastion''s walls forever. Strength through Unity. Power through Conquest. Forever.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "BASTION_CORE"}'::jsonb, '{"min_level": 99, "reputation_required": 680, "required_quests": ["fq_iron_099"]}'::jsonb, '[{"type": "travel", "target": "BASTION_CORE", "count": 1, "desc": "Return to the Bastion as the Eternal Hegemon.", "description": "Travel to BASTION CORE. (Travel to: Bastion Core)"}, {"type": "interact", "target": "npc_hegemony_commander", "count": 1, "desc": "Receive the Eternal Hegemon honors from High Commander Varkas.", "description": "Speak with npc hegemony commander. (Commander Drax at Bastion Core Command Bunker)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}, {"item_id": "eternal_hegemon_seal", "quantity": 1}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_iron.json', 99)
