values ('fq_star_001', 'The Purification Begins', 'story', 'D', 'STARFORGED_LEGION', 'DUNE_OUTSKIRTS', 'Grand Justiciar Aurelius speaks with the gravity of a man who has watched his people lose everything and chosen to build something harder in place of what was taken. The Starforged Legion arrived on Xylos as exiles — their home system shattered, their fleet battle-scarred, their code of honor the only thing that survived the journey intact. The Dune Outskirts are the first ground the Legion has claimed, and the Dune Scavengers defiling the sacred sands are the first test of whether Xylos will accept the Legion''s authority. Purify it. The Legion claims ground by right of strength. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "DUNE_OUTSKIRTS"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "kill", "target": "DUNE_SCAVENGER", "count": 5, "description": "Purify Dune Scavengers."}, {"type": "collect", "target": "sand_claw", "count": 1, "description": "Collect sand claw (x1). [Item: Sand Claw]"}]'::jsonb, '{"exp": 50, "currency": 30, "crd": 0, "rep": 30, "items": [{"item_id": "con_small_hp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_002', false, NULL, NULL, NULL, 'quest_legion.json', 0)
