values ('fq_star_005', 'The Forge That Shapes a Weapon', 'story', 'D', 'STARFORGED_LEGION', 'FORTRESS_KAELEN', 'Centurion Valka summons you to Fortress Kaelen for the specialization rite with the tone of someone delivering a verdict rather than an offer: ''Fortress Kaelen has evaluated your performance. You are material worth forging.'' In the Starforged Legion, a class specialization is not a choice about what you want to be — it is the Legion''s determination of what you are already becoming, given form and sharpened. The forge shapes the weapon. The weapon does not shape the forge. Choose within what the Legion has seen in you.', '{"npc_id": "npc_legion_class_trainer", "name": "Centurion Valka", "location": "FORTRESS_KAELEN"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_star_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_legion_class_trainer", "count": 1, "description": "Report to Centurion Valka. (Centurion Valka at Forge Canyon Depths Combat Arena)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Choose your combat specialization."}, {"type": "kill", "target": "DUNE_SCAVENGER", "count": 3, "description": "Prove your worth against Dune Gnashers. [Dune Scavenger]"}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_iron_sword", "quantity": 1}, {"item_id": "arm_iron_plate", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_star_006', true, 'on_quest_complete', 4, 'fq_star_004', 'quest_legion.json', 4)
