values ('fq_star_007', 'Fire Against Fire', 'story', 'D', 'STARFORGED_LEGION', 'SCORCHED_BADLANDS', 'Ash Hounds are fire given form and instinct — creatures that emerged from the Scorched Badlands'' aethel-charged volcanic substrate, running on combustion and predatory rage. Sergeant Korg — whose burn scars on his left arm are a record of his first Ash Hound encounter — explains the Legion''s approach to fire-creatures: ''You do not fear fire. You use fire. Your weapons are fire. Your will is fire. The Hound does not get to be the only thing burning.'' Hunt them.', '{"npc_id": "npc_drill_sergeant_korg", "name": "Centurion Valka", "location": "SCORCHED_BADLANDS"}'::jsonb, '{"min_level": 6, "reputation_required": 30, "required_quests": ["fq_star_006"]}'::jsonb, '[{"type": "kill", "target": "ASH_HOUND", "count": 5, "description": "Hunt Ash Hounds."}, {"type": "collect", "target": "ember_fang", "count": 3, "description": "Collect ember fang (x3). [Item: Ember Fang]"}]'::jsonb, '{"exp": 120, "currency": 70, "crd": 0, "rep": 70, "items": [{"item_id": "animal_fang", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_008', false, NULL, NULL, NULL, 'quest_legion.json', 6)
