values ('fq_star_009', 'The Alpha Predator Meets the Apex Legion', 'story', 'D', 'STARFORGED_LEGION', 'SCORCHED_BADLANDS', 'The Dune Stinger is the apex predator of the Scorched Badlands — the creature that everything else in this harsh landscape fears. Grand Justiciar Aurelius says the Legion''s arrival has changed the ecosystem''s top position. A Legionnaire does not exist at the bottom of any food chain. Bring the Dune Stinger down. The Ash Hounds that escort it will learn what apex means in the Legion''s presence. Leave the Stinger''s venom sac intact — it has battlefield applications. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "SCORCHED_BADLANDS"}'::jsonb, '{"min_level": 8, "reputation_required": 40, "required_quests": ["fq_star_008"]}'::jsonb, '[{"type": "kill", "target": "DUNE_STINGER", "count": 1, "description": "Hunt the Dune Stinger."}, {"type": "kill", "target": "ASH_HOUND", "count": 3, "description": "Clear Hound escorts. [Ash Hound]"}]'::jsonb, '{"exp": 250, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "venom_sac", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_star_010', false, NULL, NULL, NULL, 'quest_legion.json', 8)
