values ('fq_star_011', 'Walking Through History', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'The Mesa Warpath is where the Legion earns its next advancement — a canyon battlefield that has hosted wars since before Xylos had factions, where the walls still bear impact scars from weapons the Legion''s own historians cannot identify. Veteran Gorok, who has walked this path three times in the course of his Legion service, offers the same briefing each time: ''Walk it slowly. Look at everything. War leaves lessons in the walls.'' The Legion learns from every battlefield it encounters. The Warpath is its next classroom.', '{"npc_id": "npc_warpath_veteran", "name": "Grand Justiciar Aurelius", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 10, "reputation_required": 50, "required_quests": ["fq_star_010"]}'::jsonb, '[{"type": "travel", "target": "MESA_WARPATH", "count": 1, "description": "Enter the Mesa Warpath."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 280, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_star_012', false, NULL, NULL, NULL, 'quest_legion.json', 10)
