values ('fq_star_012', 'Strike the Forward Elements First', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'Warpath Scouts are the enemy''s eyes — forward elements whose function is to find, identify, and report on Legion positions before heavier forces engage. Veteran Gorok''s tactical briefing is concise: ''Blind the enemy before it can see you.'' The Warpath Scouts in the Mesa Warpath''s eastern corridor have been monitoring Legion supply movements for three days. Their intelligence has already reached their commanders. Remove the intelligence-gathering capability before it causes more damage than it already has.', '{"npc_id": "npc_warpath_veteran", "name": "Grand Justiciar Aurelius", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 11, "reputation_required": 55, "required_quests": ["fq_star_011"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_SCOUT", "count": 5, "description": "Eliminate enemy scouts. [Warpath Scout]"}, {"type": "collect", "target": "rare_emblem", "count": 2, "description": "Collect rare emblem (x2). [Item: Rare Emblem]"}]'::jsonb, '{"exp": 320, "currency": 170, "crd": 0, "rep": 170, "items": [{"item_id": "scrap_circuit", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_star_013', false, NULL, NULL, NULL, 'quest_legion.json', 11)
