insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_013', 'Veterans Die the Same as Recruits', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'Warpath Veterans are experienced enemy combatants — soldiers who have survived enough battles to develop the adaptive tactical thinking that makes them genuinely dangerous. (Location: Mesa Warpath, Veteran Gorok) Veteran Gorok says this without disrespect for the dead: ''Veterans die the same as recruits when the tactics are right.'' The Legion''s training is superior. The Legion''s weapons are superior. The Legion''s commitment is absolute. Prove all three against the Veterans in the Warpath''s central approach zone. Collect their insignia as documentation of the engagement.', '{"npc_id": "npc_warpath_veteran", "name": "Centurion Valka", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 12, "reputation_required": 60, "required_quests": ["fq_star_012"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_VETERAN", "count": 5, "description": "Defeat enemy veterans. [Warpath Veteran]"}, {"type": "collect", "target": "rare_emblem", "count": 2, "description": "Collect rare emblem (x2). [Item: Rare Emblem]"}]'::jsonb, '{"exp": 360, "currency": 190, "crd": 0, "rep": 200, "items": [{"item_id": "scrap_metal", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_014', false, NULL, NULL, NULL, 'quest_legion.json', 12)
