insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_014', 'A Champion''s Challenge Is a Legion Invitation', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'A Warpath Champion — an enemy warrior who has distinguished themselves enough to earn a direct challenge from other worthy combatants — has issued a formal engagement notice to the Legion''s forward units. (Location: Mesa Warpath, Veteran Gorok) In Starforged Legion doctrine, a challenge from a worthy opponent is not just accepted; it is honored. Veteran Gorok will observe the engagement from the ridge. Grand Justiciar Aurelius says: ''Show the Warpath what a Legionnaire looks like in direct combat. Make the Champion''s fall worthy of both of you.''', '{"npc_id": "npc_warpath_veteran", "name": "Grand Justiciar Aurelius", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 13, "reputation_required": 65, "required_quests": ["fq_star_013"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_CHAMPION", "count": 2, "description": "Defeat Warpath Champions in single combat."}, {"type": "collect", "target": "rare_emblem", "count": 1, "description": "Collect rare emblem (x1). [Item: Rare Emblem]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "wpn_steel_broadsword", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_star_015', false, NULL, NULL, NULL, 'quest_legion.json', 13)
