insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_015', 'The Warpath Is Cleared; The Legion Advances', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'General Kaelen''s sweep order for the Mesa Warpath is absolute: every hostile force in the Warpath''s full operational zone must be neutralized before the Legion establishes its permanent forward position. A partial sweep is a strategic liability — any remaining Scouts or Veterans represent a future threat that compounds when you least need complications. Centurion Valka supervises the final clearance personally, which means the standard for completeness is higher than it normally is. Four Scouts, four Veterans, zero exceptions.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 14, "reputation_required": 70, "required_quests": ["fq_star_014"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_SCOUT", "count": 4, "description": "Sweep Scouts. [Warpath Scout]"}, {"type": "kill", "target": "WARPATH_VETERAN", "count": 4, "description": "Sweep Veterans. [Warpath Veteran]"}]'::jsonb, '{"exp": 500, "currency": 280, "crd": 0, "rep": 300, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_016', false, NULL, NULL, NULL, 'quest_legion.json', 14)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_016', 'Superior Tactics Against Superior Numbers', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'Multiple Warpath Champions are coordinating in the Mesa Warpath''s command canyon — sharing tactical information, covering each other''s flanks, and neutralizing the individual advantage that Legion soldiers normally hold over single opponents. Veteran Gorok says this is the most tactically interesting problem the Warpath has presented: ''They are trying to be a Legion.'' The answer to a coordinated enemy, Legion doctrine states, is never matching their coordination. It is disrupting it, surgically and completely, until coordination becomes liability.', '{"npc_id": "npc_warpath_veteran", "name": "Centurion Valka", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 15, "reputation_required": 75, "required_quests": ["fq_star_015"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_CHAMPION", "count": 3, "description": "Break Champion cohort. [Warpath Champion]"}, {"type": "collect", "target": "rare_emblem", "count": 1, "description": "Collect rare emblem (x1). [Item: Rare Emblem]"}]'::jsonb, '{"exp": 520, "currency": 290, "crd": 0, "rep": 310, "items": [{"item_id": "tactical_sensor_cluster", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_star_017', false, NULL, NULL, NULL, 'quest_legion.json', 15)
