insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_017', 'The Warpath''s Payroll', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'General Kaelen''s requisition from the Warpath''s strategic materials cache requires specific components that the Legion''s forward engineering team needs for fortification construction. (Location: Mesa Warpath, Scout Jace) The Warpath Wreckers that have been stripping the battlefield''s decommissioned equipment are interfering with the recovery operation. The Legion''s forward logistics are not a negotiable resource — every hour of construction delay is a fortification gap that a Champion or Scout will eventually find. Clear the Wreckers. Retrieve the components. Deliver them by nightfall.', '{"npc_id": "npc_dune_scout", "name": "Grand Justiciar Aurelius", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 16, "reputation_required": 80, "required_quests": ["fq_star_016"]}'::jsonb, '[{"type": "collect", "target": "rare_emblem", "count": 4, "description": "Collect rare emblem (x4). [Item: Rare Emblem]"}, {"type": "kill", "target": "WARPATH_SCOUT", "count": 3, "description": "Clear the recovery zone. [Warpath Scout]"}]'::jsonb, '{"exp": 480, "currency": 260, "crd": 0, "rep": 260, "items": [{"item_id": "memory_fragment_chip", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_star_018', false, NULL, NULL, NULL, 'quest_legion.json', 16)
