values ('fq_star_019', 'The Resonance Does Not Belong Here', 'story', 'C', 'STARFORGED_LEGION', 'MESA_WARPATH', 'A Resonance Echo has formed in the Warpath''s deep canyon, drawn by the electromagnetic activity from the Sentinel Commander''s activation and now disrupting Legion communication systems. (Location: Mesa Warpath, Veteran Gorok) Grand Justiciar Aurelius is notably less interested in the theological implications than the Children of the Shard would be, or the scientific implications the Arcanum Seekers would catalog. His interest is operational: the Echo is interfering with Legion tactical coordination. Eliminate it. A Legionnaire does not permit their communications to be compromised by any entity.', '{"npc_id": "npc_warpath_veteran", "name": "Grand Justiciar Aurelius", "location": "MESA_WARPATH"}'::jsonb, '{"min_level": 18, "reputation_required": 90, "required_quests": ["fq_star_018"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_SCOUT", "count": 4, "description": "Final Scout trial. [Warpath Scout]"}, {"type": "kill", "target": "WARPATH_VETERAN", "count": 4, "description": "Final Veteran trial. [Warpath Veteran]"}, {"type": "kill", "target": "WARPATH_CHAMPION", "count": 2, "description": "Final Champion trial. [Warpath Champion]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_star_020', false, NULL, NULL, NULL, 'quest_legion.json', 18)
