values ('fq_star_020', 'Promotion Is the Legion''s Highest Gift', 'story', 'C', 'STARFORGED_LEGION', 'FORTRESS_KAELEN', 'Grand Justiciar Aurelius stands at Fortress Kaelen''s ceremony platform — not a common occurrence, as the Justiciar''s presence at individual promotions is reserved for those the Legion considers strategically significant. Your Advanced Combat elevation is, apparently, one of those. Centurion Valka is already preparing the Forge Canyon assignment briefing. The Forge Canyon Depths represent a new phase of the Legion''s Xylos campaign, and those who operate there are expected to perform at a level commensurate with their rank. Advance. The Legion is watching. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "FORTRESS_KAELEN"}'::jsonb, '{"min_level": 19, "reputation_required": 95, "required_quests": ["fq_star_019"]}'::jsonb, '[{"type": "travel", "target": "FORTRESS_KAELEN", "count": 1, "description": "Return to Fortress Kaelen."}, {"type": "collect", "target": "titan_core", "count": 1, "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_mp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_021', false, NULL, NULL, NULL, 'quest_legion.json', 19)
