values ('fq_star_021', 'Into the Forge Canyon Depths', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'The Forge Canyon Depths are where the Starforged Legion draws its name from — a canyon complex of such geological intensity and electromagnetic activity that Legion historians believe the original Starforged weapons were created here by the Aethelgardians, using the canyon''s natural forge-temperatures to work metals that no other location on Xylos could process. The Legion does not consider this heritage an accident. They consider it a sign that Xylos''s most powerful forge was waiting for the most powerful warriors. Enter and take what belongs to the Legion''s history. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "FORGE_CANYON_DEPTHS"}'::jsonb, '{"min_level": 20, "reputation_required": 100, "required_quests": ["fq_star_020"]}'::jsonb, '[{"type": "travel", "target": "FORGE_CANYON_DEPTHS", "count": 1, "description": "Enter Forge Canyon. (Travel to: Forge Canyon Depths)"}, {"type": "collect", "target": "rat_hide", "count": 2, "description": "Collect rat hide (x2). [Item: Rat Hide]"}]'::jsonb, '{"exp": 1600, "currency": 800, "crd": 240, "rep": 500, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_star_022', false, NULL, NULL, NULL, 'quest_legion.json', 20)
