values ('fq_star_022', 'Drones of an Empire That Failed', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'Titan Assembly Drones — construction machines left in the Forge Canyon Depths by Iron Hegemony engineers who began a Titan-construction project here and abandoned it when the canyon''s electromagnetic interference proved too extreme for their equipment — have been operating autonomously since the Hegemony''s withdrawal, attacking anything that enters the construction zone. Centurion Valka examines their wreckage with professional interest: ''Iron Hegemony construction is good. Not Legion good. But good.'' Destroy the Drones. Salvage the circuits for the Legion''s own construction program. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "FORGE_CANYON_DEPTHS"}'::jsonb, '{"min_level": 21, "reputation_required": 110, "required_quests": ["fq_star_021"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_DRONE", "count": 6, "description": "Destroy enemy drones. [Titan Assembly Drone]"}, {"type": "collect", "target": "circuit_fragment", "count": 2, "description": "Collect circuit fragment (x2). [Item: Circuit Fragment]"}]'::jsonb, '{"exp": 1650, "currency": 825, "crd": 247, "rep": 515, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_star_023', false, NULL, NULL, NULL, 'quest_legion.json', 21)
