values ('fq_star_023', 'Titan Sentinels Must Stand Down', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'The Titan Assembly Sentinels that the Iron Hegemony left in the Forge Canyon Depths as the final security layer are the most dangerous hardware the Hegemony built before their withdrawal — combat-optimized giants that have been running battle protocols in the canyon for months without maintenance or oversight. Grand Justiciar Aurelius reviews the specification data with the appreciation of someone who respects capable engineering regardless of who built it. Then he orders them destroyed. The Forge Canyon belongs to the Legion now. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "FORGE_CANYON_DEPTHS"}'::jsonb, '{"min_level": 22, "reputation_required": 120, "required_quests": ["fq_star_022"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 3, "description": "Destroy Sentinels. [Titan Assembly Sentinel]"}, {"type": "collect", "target": "sensor_chip", "count": 1, "description": "Collect sensor chip (x1). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 1700, "currency": 850, "crd": 255, "rep": 530, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_star_024', false, NULL, NULL, NULL, 'quest_legion.json', 22)
