values ('fq_star_024', 'Enemy Scouts in the Legion''s Forge', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'Warpath Scouts have infiltrated the Forge Canyon Depths — enemy forward elements from the Mesa Warpath command, tracking the Legion''s movement into the canyon zone and reporting back with information that will eventually result in a coordinated response the Legion would prefer to avoid. Grand Justiciar Aurelius''s instruction is tactical and final: ''We do not operate in territory while enemy intelligence assets observe us. Clear the scouts. All of them.'' Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "FORGE_CANYON_DEPTHS"}'::jsonb, '{"min_level": 23, "reputation_required": 130, "required_quests": ["fq_star_023"]}'::jsonb, '[{"type": "kill", "target": "WARPATH_SCOUT", "count": 4, "description": "Clear Scouts. [Warpath Scout]"}, {"type": "kill", "target": "WARPATH_VETERAN", "count": 3, "description": "Clear Veterans. [Warpath Veteran]"}]'::jsonb, '{"exp": 1750, "currency": 875, "crd": 262, "rep": 545, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_star_025', false, NULL, NULL, NULL, 'quest_legion.json', 23)
