values ('fq_star_026', 'The Legion Expands Its Territory', 'story', 'B', 'STARFORGED_LEGION', 'BORDER_SKIRMISH_RING', 'The Border Skirmish Ring is where the Legion''s territorial expansion meets the resistance of every other faction that has been operating in the neutral zones. Grand Justiciar Aurelius''s assessment of the Ring is strategic and direct: ''Every meter we hold here is a meter the others do not.'' The Legion''s doctrine of territorial expansion does not wait for other factions to yield ground willingly — it presents them with a situation in which yielding is the most rational choice. Enter the Ring. Begin that presentation. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 25, "reputation_required": 150, "required_quests": ["fq_star_025"]}'::jsonb, '[{"type": "travel", "target": "BORDER_SKIRMISH_RING", "count": 1, "description": "Enter. (Travel to: Border Skirmish Ring)"}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 1850, "currency": 925, "crd": 277, "rep": 575, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_star_027', false, NULL, NULL, NULL, 'quest_legion.json', 25)
