insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_028', 'The Behemoth That Doesn''t Know the Ring Changed Hands', 'story', 'B', 'STARFORGED_LEGION', 'BORDER_SKIRMISH_RING', 'An Aethel Behemoth has been using the Border Skirmish Ring as its seasonal territory for what the Legion''s ecological assessors estimate is decades — long before any faction claimed this zone. Centurion Valka frames the mission with characteristic directness: ''The Behemoth does not know the Ring changed hands. Inform it.'' The Aethel Rift Stalkers that run with the Behemoth are its escort, not its protectors. Clear the escorts first. The Behemoth will understand the message when there is nothing left to misunderstand. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "BORDER_SKIRMISH_RING"}'::jsonb, '{"min_level": 27, "reputation_required": 170, "required_quests": ["fq_star_027"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "description": "Defeat. [Aethel Behemoth]"}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 1950, "currency": 975, "crd": 292, "rep": 605, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_star_029', false, NULL, NULL, NULL, 'quest_legion.json', 27)
