insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_029', 'The Forge Canyon Yields to No One Else', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'The final Titan Assembly Sentinels in the Forge Canyon Depths represent the Iron Hegemony''s last operational presence in territory the Legion has claimed. Grand Justiciar Aurelius does not permit competing operational presences in Legion-claimed territory. These Sentinels have been running Hegemony battle protocols since the Hegemony''s withdrawal and they will continue to do so until someone destroys them. The Legion is that someone. Mastery of the Forge Canyon requires removing every piece of the previous tenant. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "FORGE_CANYON_DEPTHS"}'::jsonb, '{"min_level": 28, "reputation_required": 180, "required_quests": ["fq_star_028"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "description": "Master. [Titan Assembly Sentinel]"}, {"type": "collect", "target": "scrap_core", "count": 1, "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 2000, "currency": 1000, "crd": 300, "rep": 620, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_star_030', false, NULL, NULL, NULL, 'quest_legion.json', 28)
