values ('fq_star_031', 'The Legion''s Reach Extends to the Stars', 'story', 'A', 'STARFORGED_LEGION', 'ORBITAL_SENTINEL_COMMAND', 'Grand Justiciar Aurelius stands at the Orbital Sentinel Command''s threshold and makes the announcement that no previous Legion commander has been able to make: ''The Legion reaches the stars.'' Not metaphorically — the Orbital Sentinel Command represents the Legion''s first foothold above Xylos''s atmosphere, a position that allows the Legion to observe every other faction''s movements from a height that confers absolute tactical advantage. Report to Orbital Command. The Legion''s campaign on Xylos has entered its orbital phase. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 200, "required_quests": ["fq_star_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "description": "Take to the skies. (Travel to: Orbital Sentinel Command)"}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 650, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_star_032', false, NULL, NULL, NULL, 'quest_legion.json', 30)
