values ('fq_star_032', 'The Drake Is the Test of the Expanse', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'The Ashen Drake in the Cradle Expanse is the apex creature of the most contested zone on Xylos — a living measure of whether the Legion''s soldiers are genuinely prepared for what the Expanse requires. Grand Justiciar Aurelius frames the Drake engagement as a test, not just a tactical objective: ''The Drake does not fear anything in the Expanse. That changes today.'' Observe the Drake''s behavior. The observation data alone has strategic value. Then challenge it. The Drake''s defeat is the Legion''s declaration that the Expanse answers to the Legion now. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 225, "required_quests": ["fq_star_031"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Challenge the Drake. [Ashen Drake]"}, {"type": "collect", "target": "ancient_scale", "count": 1, "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 2150, "currency": 1075, "crd": 537, "rep": 665, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_star_033', false, NULL, NULL, NULL, 'quest_legion.json', 31)
