values ('fq_star_033', 'The Expanse Is Being Armored Against Us', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'The Aethel Iron Carapace creatures spreading through the Cradle Expanse are a direct strategic threat to the Legion''s supply lanes — their shells deflect standard Legion weapons and their territorial clustering in the Expanse''s mineral zones blocks access to resources the Legion needs for the Forge Canyon construction program. Centurion Valka has already run the breach calculations. Six Carapace must be cleared from the primary supply corridor. Three crystal cores recovered for the armor-penetration research program. This is the Legion''s resource war. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 250, "required_quests": ["fq_star_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 6, "description": "Breach. [Aethel Iron Carapace]"}, {"type": "collect", "target": "carapace_fragment", "count": 3, "description": "Collect carapace fragment (x3). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 680, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_star_034', false, NULL, NULL, NULL, 'quest_legion.json', 32)
