values ('fq_star_035', 'The Void''s Advance Guard in the Expanse', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'Aethel Abyssal Reavers have penetrated the Cradle Expanse''s Legion-controlled sectors — the void''s forward elements, testing the Legion''s defensive perimeter with the methodical patience of something that does not feel urgency. The Legion''s code of honor does not extend to void entities; there is no worthy combat with the void, only elimination. Four Reavers, cleared from the Legion''s operational zone, is today''s answer to the void''s advance. Tomorrow''s answer will be the same. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 34, "reputation_required": 300, "required_quests": ["fq_star_034"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "description": "Engage. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "void_channeler_core", "count": 1, "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2300, "currency": 1150, "crd": 558, "rep": 710, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_star_036', false, NULL, NULL, NULL, 'quest_legion.json', 34)
