values ('fq_star_036', 'Nothing Flies in the Expanse Without Permission', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'Aethel Rift Stalkers are using the Cradle Expanse''s electromagnetic currents as patrol routes above the Legion''s operational zones — maintaining aerial superiority over terrain the Legion has claimed on the ground. Grand Justiciar Aurelius''s operational doctrine covers this explicitly: the Legion claims all dimensions of the territory it occupies, not just the ground layer. Clear the Rift Stalkers from the Expanse airspace. Neutralize the Void Channelers that are directing their movement patterns. Legion territory is Legion territory at all altitudes. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 35, "reputation_required": 325, "required_quests": ["fq_star_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Defend. [Aethel Rift Stalker]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Neutralize. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2350, "currency": 1175, "crd": 587, "rep": 725, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_star_037', false, NULL, NULL, NULL, 'quest_legion.json', 35)
