insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_038', 'The Expanse Belongs to the Strongest', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'The Aethel Iron Carapace creatures have regrouped in the Expanse''s northern sectors — there are eight of them now, a larger concentration than the first engagement. (Location: Cradle Expanse, General Kaelen) Centurion Valka is not concerned. The Legion does not operate on the principle that a larger number of the same threat constitutes a different kind of problem. Eight Carapace are eight individual targets with the same solution. Clear them. Recover the crystal cores. The Expanse belongs to whoever is strong enough to keep it. The Legion is that whoever.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 37, "reputation_required": 375, "required_quests": ["fq_star_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Conquer. [Aethel Iron Carapace]"}, {"type": "collect", "target": "carapace_fragment", "count": 1, "description": "Collect carapace fragment (x1). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 2450, "currency": 1225, "crd": 612, "rep": 755, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_star_039', false, NULL, NULL, NULL, 'quest_legion.json', 37)
