insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_039', 'The Void''s Counter-Offensive Must Fail', 'story', 'A', 'STARFORGED_LEGION', 'CRADLE_EXPANSE', 'The Aethel Abyssal Reavers and Void Channelers have mounted a coordinated incursion into the Expanse — five Reavers supported by three Channelers, moving with the tactical discipline that indicates external coordination. (Location: Cradle Expanse, General Kaelen) Grand Justiciar Aurelius''s battle briefing contains a note that his soldiers rarely hear: ''This is organized.'' The void''s counter-offensive against the Legion''s Expanse positions is the most sophisticated threat the Reavers have presented. Break it surgically. Void Channelers first — remove the coordination. Then the Reavers. Leave no element of this counter-offensive operational.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 400, "required_quests": ["fq_star_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "description": "Counter. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Silence. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2500, "currency": 1250, "crd": 606, "rep": 770, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_star_040', false, NULL, NULL, NULL, 'quest_legion.json', 38)
