insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_040', 'Master of the Starforged Legion', 'story', 'A', 'STARFORGED_LEGION', 'FORTRESS_KAELEN', 'Grand Justiciar Aurelius stands at the ceremony platform in Fortress Kaelen''s inner sanctum — the chamber that has witnessed every major elevation in the Legion''s history on Xylos — and the ceremony is brief and absolute, as all Legion ceremonies are. The Master of the Starforged elevation requires the final trial: the Drake defeated a third time, a Behemoth engaged at full strength, a Leviathan from the deep guided to rest. These are the three creatures that measure the limits of what a Legionnaire can face. Pass all three. The Legion''s highest recognition awaits. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "FORTRESS_KAELEN"}'::jsonb, '{"min_level": 39, "reputation_required": 425, "required_quests": ["fq_star_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Conquer Drake. [Ashen Drake]"}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "description": "Conquer Behemoth. [Aethel Behemoth]"}, {"type": "kill", "target": "WARPATH_CHAMPION", "count": 2, "description": "Conquer Champions. [Warpath Champion]"}]'::jsonb, '{"exp": 2550, "currency": 1275, "crd": 637, "rep": 785, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_star_041', false, NULL, NULL, NULL, 'quest_legion.json', 39)
