values ('fq_star_041', 'The Legion Descends Into the Darkness', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'Grand Justiciar Aurelius describes the Void Echo Chasm to new arrivals with the candor that experienced warriors use when they want their soldiers to survive: ''Everything in the Chasm will try to kill you. Some of it will succeed if you let your guard down. Do not let your guard down.'' The Legion does not romanticize the darkness the way the Children of the Shard do, or study it the way the Arcanum Seekers would. The Legion enters it because the Legion enters every territory that needs to be controlled. Light in the Chasm: establish the Legion''s presence. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 450, "required_quests": ["fq_star_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "description": "Enter. (Travel to: Void Echo Chasm)"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2600, "currency": 1300, "crd": 630, "rep": 800, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_042', false, NULL, NULL, NULL, 'quest_legion.json', 40)
