values ('fq_star_044', 'Execute With Precision, Not Ceremony', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'Corrupted Behemoths in the Chasm''s lower levels are the most dangerous physical threats the Legion has encountered in the Void Echo Chasm — creatures that were once among the most powerful living entities on Xylos, now driven by pure corrupted aggression without the natural territorial caution that made them manageable before. Grand Justiciar Aurelius''s battle brief is three words: ''Execute with precision.'' No ceremony, no theological consideration, no hesitation. These creatures are threats. The Legion eliminates threats. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 600, "required_quests": ["fq_star_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Execute. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 2750, "currency": 1375, "crd": 666, "rep": 845, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_045', false, NULL, NULL, NULL, 'quest_legion.json', 43)
