insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_048', 'The Shattered Heart Is Legion Territory Now', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'The Shattered Heart — where Xylos''s aethel core cracked under the Great Severance — is the kind of zone that other factions approach with caution or reverence. (Location: Void Echo Chasm, General Kaelen) The Legion approaches it with a column of soldiers, a logistics train, and a deployment plan. Grand Justiciar Aurelius briefs the Shattered Heart entry with the directness of someone who considers geological drama irrelevant to tactical planning: ''It is terrain. Difficult terrain, but terrain. Establish Legion presence. All other considerations are secondary.''', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 800, "required_quests": ["fq_star_047"]}'::jsonb, '[{"type": "travel", "target": "SHATTERED_HEART", "count": 1, "description": "Breach. (Travel to: Shattered Heart, Shattered Heart)"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 2950, "currency": 1475, "crd": 714, "rep": 905, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_star_049', false, NULL, NULL, NULL, 'quest_legion.json', 47)
