insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_049', 'The Drake''s Last Stand, Against the Legion''s First Entry', 'story', 'S', 'STARFORGED_LEGION', 'SHATTERED_HEART', 'In the Shattered Heart, an Ashen Drake has maintained its territory since before any faction''s arrival on Xylos — an ancient creature whose fire has been burning in the planet''s aethel-rich geological core for centuries. Centurion Valka acknowledges its age without sentimentality: ''Old does not mean superior. Old means experienced.'' The Drake''s experience is considerable. The Legion''s training is absolute. Guide it to rest by superior force and discipline. The Shattered Heart is the Legion''s now. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 49, "reputation_required": 850, "required_quests": ["fq_star_048"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Redeem. [Ashen Drake]"}, {"type": "kill", "target": "DRAKE_MINION", "count": 5, "description": "Clear Minions. [Drake Minion]"}]'::jsonb, '{"exp": 3050, "currency": 1525, "crd": 738, "rep": 935, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_050', false, NULL, NULL, NULL, 'quest_legion.json', 48)
