insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_051', 'Total Void War in the Chasm', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'The Legion''s total void war doctrine — developed by Grand Justiciar Aurelius following three months of Chasm engagement analysis — requires the systematic elimination of void presence from Legion-designated operational zones without partial clearance or negotiated withdrawal. (Location: Void Echo Chasm, General Kaelen) Eight Void Reavers, five Void Channelers, all zones. Centurion Valka makes the briefing simpler than the doctrine: ''All of them. Every zone. No survivors.'' This is not a proportional response. This is Legion standard operating procedure.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 950, "required_quests": ["fq_star_050"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "description": "Destroy. [Void Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Destroy. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 3150, "currency": 1575, "crd": 762, "rep": 965, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_star_052', false, NULL, NULL, NULL, 'quest_legion.json', 50)
