insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_059', 'The Legion Banishes the Harbinger', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'The Abyss Harbinger has entered the Void Echo Chasm. Grand Justiciar Aurelius''s battle briefing, for the first time in the Legion''s Xylos campaign, takes more than five minutes to deliver — because the Harbinger is unlike any previous target, operating at a scale that required the Legion to revise its standard combat doctrine for this single engagement. The briefing ends: ''The Harbinger believes the Chasm belongs to the void. The Legion disagrees. Demonstrate that disagreement with full force. For the homeworld. For the code. For every soldier who did not survive to reach this moment.'' Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 59, "reputation_required": 1350, "required_quests": ["fq_star_058"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "BANISH HARBINGER. [Abyss Harbinger]"}, {"type": "collect", "target": "abyss_fragment", "count": 1, "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 3550, "currency": 1775, "crd": 858, "rep": 1085, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_star_060', false, NULL, NULL, NULL, 'quest_legion.json', 58)
