values ('fq_star_065', 'The Siphon''s Core: The Legion Arrives', 'story', 'S', 'STARFORGED_LEGION', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core — where the Concordium built their entire civilization and from which every faction on Xylos draws their strategic planning — is where the Legion''s Xylos campaign reaches its highest strategic objective. Grand Justiciar Aurelius''s address to the Legion column before entry is the longest speech anyone has heard him give: it ends with, ''The Siphon is the prize. We enter as conquerors.'' The Children of the Shard built a religion around it. The Legion intends to build a kingdom. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 1650, "required_quests": ["fq_star_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "description": "Enter. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 3800, "currency": 1900, "crd": 918, "rep": 1160, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_066', false, NULL, NULL, NULL, 'quest_legion.json', 64)
