values ('fq_star_067', 'The Siphon''s Ancient Guardians Fall to the Legion', 'story', 'S', 'STARFORGED_LEGION', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths in the Aethel Siphon Core''s inner zones are the most powerful physical obstacles the Legion has faced in the entire Xylos campaign. Grand Justiciar Aurelius does not downplay this: ''They are stronger than anything we have fought here. That is why this test matters.'' The Legion''s code states that the measure of a force''s true capability is what it defeats when the enemy is at its strongest. Face the Behemoths in the Core''s inner sanctum. The Legion''s strength must be demonstrated at the Siphon''s heart. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 1750, "required_quests": ["fq_star_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Defend. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 3900, "currency": 1950, "crd": 942, "rep": 1190, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_star_068', false, NULL, NULL, NULL, 'quest_legion.json', 66)
