values ('fq_star_071', 'The Forge of Legend: The Legion Claims Prima Materia', 'story', 'S', 'STARFORGED_LEGION', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge is where the highest-value material on Xylos is processed — a zone that every faction has tried and failed to hold because the Prima Materia itself resists extraction by those who approach it incorrectly. Grand Justiciar Aurelius''s tactical note on this failure: ''They approached it as a resource. We approach it as a conquest.'' The Legion does not extract Prima Materia. The Legion claims the Forge. Whatever the Forge produces, the Legion owns. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 1950, "required_quests": ["fq_star_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "description": "Enter. (Travel to: Prima Materia Forge, Shattered Heart)"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 2, "description": "Collect raw aethel fragment (x2). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 4100, "currency": 2050, "crd": 990, "rep": 1250, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_072', false, NULL, NULL, NULL, 'quest_legion.json', 70)
