values ('fq_star_072', 'Clearing the Forge''s Approaches', 'story', 'S', 'STARFORGED_LEGION', 'PRIMA_MATERIA_FORGE', 'Aethel Iron Carapace creatures have armored the Prima Materia Forge''s outer processing ring against entry — layers of carapace-shell forming organic barricades that the Legion''s standard approach techniques cannot breach without clearing the creatures themselves. Centurion Valka''s engineering assessment is direct: ''The barricades are alive. Eliminate the alive parts. The barricades become rubble.'' Clear the Carapace. The Forge''s approach corridor must be open before the Legion''s main engineering team can advance. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Centurion Valka", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 2000, "required_quests": ["fq_star_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Conquer. [Aethel Iron Carapace]"}, {"type": "collect", "target": "carapace_fragment", "count": 1, "description": "Collect carapace fragment (x1). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 4150, "currency": 2075, "crd": 1002, "rep": 1265, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_star_073', false, NULL, NULL, NULL, 'quest_legion.json', 71)
