values ('fq_star_073', 'The Void Cannot Have the Forge', 'story', 'S', 'STARFORGED_LEGION', 'PRIMA_MATERIA_FORGE', 'Aethel Abyssal Reavers and a Gravity Titan have combined their presence in the Prima Materia Forge''s inner processing zone — the Reavers feeding on the Forge''s ambient Prima Materia output while the Titan''s gravity well creates conditions that enhance their void feeding efficiency. Grand Justiciar Aurelius calls this ''an improvised supply chain for the void.'' The Legion''s response to the void establishing supply chains inside Legion-claimed territory is not complicated: destroy the supply chain, eliminate both elements, and deny the void the resource advantage it was building. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 2050, "required_quests": ["fq_star_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Purge. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Silence. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 4200, "currency": 2100, "crd": 1014, "rep": 1280, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_star_074', false, NULL, NULL, NULL, 'quest_legion.json', 72)
