values ('fq_star_076', 'The Trial of Legend in the Prima Materia Forge', 'story', 'S', 'STARFORGED_LEGION', 'PRIMA_MATERIA_FORGE', 'The Gravity Titan that guards the Prima Materia Forge''s ultimate processing chamber is the apex challenge of the Legion''s Xylos campaign — a creature of such mass and gravitational influence that it represents, in Grand Justiciar Aurelius''s own words, ''the hardest thing we have faced on this planet.'' The Trial of Legend is not just about winning. It is about winning at the highest level the Legion can be tested at, against an opponent that gives the test full gravity. The pun is not acknowledged by Grand Justiciar Aurelius. The mission is. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 2200, "required_quests": ["fq_star_075"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Conquer Titan. [Gravity Titan]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Conquer Harbinger. [Abyss Harbinger]"}]'::jsonb, '{"exp": 4350, "currency": 2175, "crd": 1050, "rep": 1325, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_star_077', false, NULL, NULL, NULL, 'quest_legion.json', 75)
