values ('fq_star_077', 'The Legend Returns to the Legion', 'story', 'S', 'STARFORGED_LEGION', 'PRIMA_MATERIA_FORGE', 'Grand Justiciar Aurelius stands at Fortress Kaelen''s ceremony hall for the final time this campaign cycle, and what he says is the shortest possible completion of the Legion''s highest ceremony: ''You carried the code. The code carried the Legion. Return.'' The Prima Materia Forge is secured. The Void Echo Chasm has been cleared. The Severance Faultline has been crossed. The Aethel Siphon Core is under Legion control. The Cradle Expanse answers to the Legion''s authority. Return to Fortress Kaelen. The legend is complete. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 2250, "required_quests": ["fq_star_076"]}'::jsonb, '[{"type": "travel", "target": "FORTRESS_KAELEN", "count": 1, "description": "Return. (Travel to: Fortress Kaelen)"}, {"type": "collect", "target": "ancient_scale", "count": 1, "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 4400, "currency": 2200, "crd": 1062, "rep": 1340, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_star_078', false, NULL, NULL, NULL, 'quest_legion.json', 76)
