values ('fq_star_099', 'One Last Battle Before the Eternal Gate', 'story', 'S', 'STARFORGED_LEGION', 'VOID_ECHO_CHASM', 'Grand Justiciar Aurelius stands at the approach to the Eternal Gate — the threshold that Legion scripture describes as the final test a Legionnaire must pass before their deeds are recorded in the Legion''s permanent record. (Location: Void Echo Chasm, General Kaelen) One last Gravity Titan holds the pass. It is not a coincidence that the Legion''s history placed this creature here as the final obstacle; the universe arranges such things for those who carry the code correctly. Defeat the Titan. The Gate is open to those who have earned it.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 2300, "required_quests": ["fq_star_098"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Conquer Jotunn. [Gigantic Jotunn]"}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Conquer Drake. [Ashen Drake]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Conquer Harbinger. [Abyss Harbinger]"}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_star_100', false, NULL, NULL, NULL, 'quest_legion.json', 98)
