insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_100', 'The Eternal Gate Recognizes the Legion', 'story', 'SS', 'STARFORGED_LEGION', 'FORTRESS_KAELEN', 'Grand Justiciar Aurelius speaks at the Eternal Gate with the economy of language that he has always used for moments of genuine weight: ''The Legion has found its home on Xylos. The code holds. The homeworld was not the last word — it was the first word of this sentence. Xylos is the next.'' Return to Fortress Kaelen. The Eternal Gate has opened for the Starforged Legion. What was taken from them across the stars has been rebuilt here, with stronger walls, stronger soldiers, and a code that survived everything the void could throw at it. Quest giver: General Kaelen at Fortress Kaelen War Room.', '{"npc_id": "npc_legion_general", "name": "Grand Justiciar Aurelius", "location": "FORTRESS_KAELEN"}'::jsonb, '{"min_level": 99, "reputation_required": 2350, "required_quests": ["fq_star_099"]}'::jsonb, '[{"type": "travel", "target": "FORTRESS_KAELEN", "count": 1, "description": "Return as Eternal Legionnaire. (Travel to: Fortress Kaelen)"}, {"type": "interact", "target": "npc_legion_general", "count": 1, "description": "Receive Grand Justiciar Aurelius''s eternal commendation. (General Kaelen at Fortress Kaelen War Room)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_legion.json', 99)
