insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_001', 'Your First Contract', 'story', 'D', 'MERIDIAN_CARTEL', 'CORAL_WETLANDS', 'Don Vercelli Mox — the Meridian Cartel''s most feared and best-dressed power broker — does not waste pleasantries. Every relationship in the Cartel is a transaction, and yours begins here: the Coral Wetlands are prime Cartel real estate, and Cave Rats have been eating into the raw material supply chain''s profit margins. The contract is simple. The message it sends is simpler: in the Cartel, you earn your place or you don''t have one.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "CORAL_WETLANDS"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "kill", "target": "CAVE_RAT", "count": 5, "desc": "Harvest Cave Rats for raw materials.", "description": "Defeat Cave Rat (x5)."}, {"type": "collect", "target": "rat_tail", "count": 1, "desc": "File your reclamation manifest.", "description": "Collect rat tail (x1). [Item: Rat Tail]"}]'::jsonb, '{"exp": 50, "currency": 30, "crd": 0, "rep": 30, "items": [{"item_id": "con_small_hp_cell", "quantity": 3}, {"item_id": "scrap_metal", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_002', false, NULL, NULL, NULL, 'quest_meridian.json', 0)
