values ('fq_merid_002', 'Property Value', 'story', 'D', 'MERIDIAN_CARTEL', 'CORAL_WETLANDS', 'Don Vercelli Mox explains the Coral Wetlands'' situation with the dispassion of a property assessor: the tidal zones are worth six times their current value if they can be developed for Cartel shipping docks. Wetland Crawlers infesting the shoreline have depressed that value and delayed two dock permits already. In the Cartel''s world, every creature that costs more alive than it does dead is already a liquidation order. These Crawlers cost considerably more alive.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "CORAL_WETLANDS"}'::jsonb, '{"min_level": 1, "reputation_required": 5, "required_quests": ["fq_merid_001"]}'::jsonb, '[{"type": "kill", "target": "WETLAND_CRAWLER", "count": 5, "desc": "Liquidate Wetland Crawlers.", "description": "Defeat Wetland Crawler (x5)."}, {"type": "collect", "target": "crab_shell", "count": 1, "desc": "Submit tidal zone asset report.", "description": "Collect crab shell (x1). [Item: Crab Shell]"}]'::jsonb, '{"exp": 55, "currency": 35, "crd": 0, "rep": 35, "items": [{"item_id": "con_small_mp_cell", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_003', false, NULL, NULL, NULL, 'quest_meridian.json', 1)
