values ('fq_merid_005', 'Renegotiating Your Terms', 'tutorial', 'D', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'Don Vercelli Mox reviews quarterly performance with the same dispassion he applies to everything. The verdict is implicit in the summons to Port Meridian: you have earned a renegotiation. In the Cartel, specialization is not a gift — it is a clause in a revised contract that defines your market value for every mission that follows. Captain Vex handles contract upgrades and tactical specialization. Choose the clause that makes you worth the most. In the Cartel, this is the only relevant question.', '{"npc_id": "npc_meridian_class_trainer", "name": "Captain Vex", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_merid_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_meridian_class_trainer", "count": 1, "desc": "Negotiate your specialization contract with Captain Vex.", "description": "Speak with npc meridian class trainer. (Captain Vex at Port Meridian Covert Training Facility)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "desc": "Sign the class specialization agreement.", "description": "Speak with class change screen."}, {"type": "kill", "target": "CAVE_RAT", "count": 3, "desc": "Demonstrate ROI against Coral Serpents.", "description": "Defeat Cave Rat (x3)."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_hunter_dagger", "quantity": 1}, {"item_id": "arm_leather_tunic", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_merid_006', true, 'on_quest_complete', 4, 'fq_merid_004', 'quest_meridian.json', 4)
