values ('fq_merid_006', 'Untapped Territory', 'story', 'D', 'MERIDIAN_CARTEL', 'SMUGGLER_JUNGLE', 'The Smuggler Jungle is the one zone on Xylos where goods move without oversight — which is exactly why the Meridian Cartel has not yet made it theirs. Don Vercelli Mox describes this as ''a market running at 30% efficiency without Cartel management.'' The other factions avoid it because it''s lawless. The Cartel sees it differently: lawless means the contracts have not been written yet. Be the first one in. Establish a trading post. Write the first contract.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "SMUGGLER_JUNGLE"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_merid_005"]}'::jsonb, '[{"type": "travel", "target": "SMUGGLER_JUNGLE", "count": 1, "desc": "Enter the Smuggler Jungle.", "description": "Travel to SMUGGLER JUNGLE. (Travel to: Smuggler Jungle)"}, {"type": "collect", "target": "drake_heart", "count": 1, "desc": "Deploy a trading post beacon.", "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_merid_007', false, NULL, NULL, NULL, 'quest_meridian.json', 5)
