values ('fq_merid_007', 'The Competition Clause', 'story', 'D', 'MERIDIAN_CARTEL', 'SMUGGLER_JUNGLE', 'Jungle Stalkers have been hunting Cartel supply caravans moving through the new trading post''s access routes — eating into delivery margins and discouraging the independent operators whose business Don Vercelli Mox is counting on. (Location: Smuggler Jungle, Sly) Sly, the Cartel''s jungle-network fixer, puts it simply: ''Every caravan the Stalkers take is a contract the Cartel doesn''t get paid on.'' In the Cartel''s standard commercial agreement, predators that eat revenue are competitors. Remove them.', '{"npc_id": "npc_shady_smuggler", "name": "Don Vercelli Mox", "location": "SMUGGLER_JUNGLE"}'::jsonb, '{"min_level": 6, "reputation_required": 25, "required_quests": ["fq_merid_006"]}'::jsonb, '[{"type": "kill", "target": "JUNGLE_STALKER", "count": 5, "desc": "Remove Jungle Stalker competition.", "description": "Defeat Jungle Stalker (x5)."}, {"type": "collect", "target": "stalker_fang", "count": 2, "desc": "Recover stolen Cartel supplies.", "description": "Collect stalker fang (x2). [Item: Stalker Fang]"}]'::jsonb, '{"exp": 120, "currency": 70, "crd": 0, "rep": 70, "items": [{"item_id": "animal_fang", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_008', false, NULL, NULL, NULL, 'quest_meridian.json', 6)
