insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_011', 'The Heart of the Deal', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'The Black Dock Market is the Cartel''s crown jewel — an underground trading hub where every faction, every faction-adjacent operator, and every independent on Xylos eventually comes to do business. Don Vercelli Mox built it from a single smuggler''s berth twenty years ago, deal by deal. Now the supply chain feeding it is under pressure from multiple competitors. Before you operate at this level of Cartel business, you need to understand what is at stake. Enter the Black Dock. See what the Cartel protects.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 10, "reputation_required": 45, "required_quests": ["fq_merid_010"]}'::jsonb, '[{"type": "travel", "target": "BLACK_DOCK_MARKET", "count": 1, "desc": "Enter the Black Dock Market.", "description": "Travel to BLACK DOCK MARKET. (Travel to: Black Dock Market)"}, {"type": "collect", "target": "thick_hide", "count": 2, "desc": "File your market security assessment.", "description": "Collect thick hide (x2). [Item: Thick Hide]"}]'::jsonb, '{"exp": 280, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_012', false, NULL, NULL, NULL, 'quest_meridian.json', 10)
