insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_012', 'Commission or Closure', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'The Black Dock Smugglers operating without Cartel commission are not just a revenue problem — they are a structural threat. (Location: Black Dock Market, Don Vercelli) If independent operators can trade in Cartel territory without paying tribute, the message to every other trader in the network is that the Cartel''s authority is negotiable. Don Vercelli Mox''s authority is not negotiable. The commission rate is set. The enforcement policy is simple: pay or stop operating. Most choose wrong.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 11, "reputation_required": 50, "required_quests": ["fq_merid_011"]}'::jsonb, '[{"type": "kill", "target": "BLACK_DOCK_SMUGGLER", "count": 6, "desc": "Enforce monopoly on Smugglers.", "description": "Defeat Black Dock Smuggler (x6)."}, {"type": "collect", "target": "contraband_core", "count": 1, "desc": "Collect outstanding commission.", "description": "Collect contraband core (x1). [Item: Contraband Core]"}]'::jsonb, '{"exp": 320, "currency": 170, "crd": 0, "rep": 170, "items": [{"item_id": "scrap_metal", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_merid_013', false, NULL, NULL, NULL, 'quest_meridian.json', 11)
