insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_013', 'Counterproposal', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'Three Cartel middle managers are dead in two days. (Location: Black Dock Market, Don Vercelli) The Black Dock Assassins behind it are working for a rival network — rumored to be OmniCorp-funded — attempting a hostile restructuring of Cartel operations at the Dock. Don Vercelli Mox reads the intelligence report with the precise calm of someone who has survived six previous hostile takeover attempts. ''Our counterproposal,'' he says, ''is that they stop existing.'' The boardroom just looks different in the Cartel.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 12, "reputation_required": 55, "required_quests": ["fq_merid_012"]}'::jsonb, '[{"type": "kill", "target": "BLACK_DOCK_ASSASSIN", "count": 5, "desc": "Execute reverse takeover on Assassins.", "description": "Defeat Black Dock Assassin (x5)."}, {"type": "collect", "target": "mutant_claw", "count": 1, "desc": "Seize their assassination contracts.", "description": "Collect mutant claw (x1). [Item: Mutant Claw]"}]'::jsonb, '{"exp": 360, "currency": 190, "crd": 0, "rep": 200, "items": [{"item_id": "scrap_circuit", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_014', false, NULL, NULL, NULL, 'quest_meridian.json', 12)
