values ('fq_merid_014', 'Terms Not Open for Discussion', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'Black Dock Enforcers run a protection racket across the market''s eastern berths — a racket that operates without Cartel permission, without Cartel oversight, and without Cartel revenue sharing. (Location: Black Dock Market, Don Vercelli) Don Vercelli Mox sent an acquisition offer. They sent the courier back without a reply. This is, in the Cartel''s legal framework, a breach of commercial terms. The Cartel''s standard breach remedy is immediate and non-negotiable. Acquire the operation. The terms are not open for discussion.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 13, "reputation_required": 60, "required_quests": ["fq_merid_013"]}'::jsonb, '[{"type": "kill", "target": "BLACK_DOCK_ENFORCER", "count": 3, "desc": "Acquire Enforcer operations.", "description": "Defeat Black Dock Enforcer (x3)."}, {"type": "collect", "target": "rare_emblem", "count": 1, "desc": "Claim the protection racket deed.", "description": "Collect rare emblem (x1). [Item: Rare Emblem]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "rusted_plate", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_015', false, NULL, NULL, NULL, 'quest_meridian.json', 13)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_015', 'Quarterly Deregistration', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'Madam Z conducts the Black Dock''s quarterly audit with the thoroughness of someone who has found, in twenty years of operation, that unlicensed traders always underestimate the Cartel''s record-keeping. (Location: Black Dock Market, Madam Z) The audit is complete. The deregistration list is comprehensive. Smugglers operating without current permits, Assassins contracted outside Cartel channels — they have all been identified. Their continued existence is a footnote on an otherwise clean ledger. Close the footnotes.', '{"npc_id": "npc_black_market_dealer", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 14, "reputation_required": 65, "required_quests": ["fq_merid_014"]}'::jsonb, '[{"type": "kill", "target": "BLACK_DOCK_SMUGGLER", "count": 4, "desc": "Deregister unlicensed Smugglers.", "description": "Defeat Black Dock Smuggler (x4)."}, {"type": "kill", "target": "BLACK_DOCK_ASSASSIN", "count": 4, "desc": "Deregister hostile Assassins.", "description": "Defeat Black Dock Assassin (x4)."}]'::jsonb, '{"exp": 500, "currency": 280, "crd": 0, "rep": 300, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_merid_016', false, NULL, NULL, NULL, 'quest_meridian.json', 14)
