values ('fq_merid_020', 'Your Q1 Performance Review', 'story', 'C', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'Don Vercelli Mox conducts performance reviews the way he conducts everything: with complete information, no unnecessary sentiment, and a clear sense of what the numbers mean. Your numbers exceed projection. The Cartel''s Advanced Contractor tier comes with enhanced access to the Sunken Aethel Ruin operations, expanded commission authority, and the quiet knowledge that you are now, in the Cartel''s internal taxonomy, someone worth keeping. Return to Port Meridian. Sign the new contract.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 19, "reputation_required": 90, "required_quests": ["fq_merid_019"]}'::jsonb, '[{"type": "travel", "target": "PORT_MERIDIAN", "count": 1, "desc": "Return to Port Meridian headquarters.", "description": "Travel to PORT MERIDIAN. (Travel to: Port Meridian)"}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Sign your Advanced Contractor contract.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_merid_021', false, NULL, NULL, NULL, 'quest_meridian.json', 19)
