values ('fq_merid_021', 'Asset Acquisition', 'exploration', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'The Sunken Aethel Ruin holds Precursor assets. The Cartel must acquire them before our competitors do. First-mover advantage is everything. Quest giver: Kip at Sunken Aethel Ruin Dockside.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 20, "reputation_required": 1140, "required_quests": ["fq_merid_020"]}'::jsonb, '[{"type": "travel", "target": "SUNKEN_AETHEL_RUIN", "count": 1, "desc": "Enter the Sunken Aethel Ruin.", "description": "Travel to SUNKEN AETHEL RUIN. (Travel to: Sunken Aethel Ruin)"}, {"type": "collect", "target": "monster_material", "count": 2, "desc": "Catalog acquirable assets.", "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 600, "currency": 350, "crd": 105, "rep": 350, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_merid_022', false, NULL, NULL, NULL, 'quest_meridian.json', 20)
