values ('fq_merid_022', 'Purifier Portfolio', 'hunt', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Cradle Purifiers guard the Ruin''s most valuable chambers. (Location: Sunken Aethel Ruin, Kip) Their defense protocols are a sunk cost — write them off.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 21, "reputation_required": 1200, "required_quests": ["fq_merid_021"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_PURIFIER", "count": 4, "desc": "Write off Cradle Purifiers.", "description": "Defeat Cradle Purifier (x4)."}, {"type": "collect", "target": "aethel_crystal_core", "count": 2, "desc": "Secure chamber access codes.", "description": "Collect aethel crystal core (x2). [Item: Aethel Crystal Core]"}]'::jsonb, '{"exp": 650, "currency": 380, "crd": 114, "rep": 380, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_merid_023', false, NULL, NULL, NULL, 'quest_meridian.json', 21)
