values ('fq_merid_023', 'Sentinel Assets', 'boss', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Cradle Sentinels guard the Ruin''s main vault. (Location: Sunken Aethel Ruin, Don Vercelli) The Cartel has a saying: every locked door is just a late payment. Force the acquisition.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 22, "reputation_required": 1260, "required_quests": ["fq_merid_022"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_SENTINEL", "count": 3, "desc": "Force-acquire Sentinel-guarded assets.", "description": "Defeat Cradle Sentinel (x3)."}, {"type": "collect", "target": "aethel_core_shard", "count": 1, "desc": "Catalog the vault contents.", "description": "Collect aethel core shard (x1). [Item: Aethel Core Shard]"}]'::jsonb, '{"exp": 750, "currency": 420, "crd": 126, "rep": 450, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_merid_024', false, NULL, NULL, NULL, 'quest_meridian.json', 22)
