values ('fq_merid_024', 'Behemoth Investment', 'boss', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Aethel Behemoths are living capital. (Location: Sunken Aethel Ruin, Kip) Their organs trade at premium prices. Make the investment — harvest the returns.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 23, "reputation_required": 1320, "required_quests": ["fq_merid_023"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "desc": "Harvest Behemoth organ assets.", "description": "Defeat Aethel Behemoth (x2)."}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "desc": "File the organ harvesting manifest.", "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 850, "currency": 460, "crd": 138, "rep": 480, "items": [{"item_id": "mutant_heart_tissue", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_merid_025', false, NULL, NULL, NULL, 'quest_meridian.json', 23)
