values ('fq_merid_025', 'Leviathan Futures', 'boss', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Sunken Aethel Leviathans are the ultimate commodity. (Location: Sunken Aethel Ruin, Don Vercelli) Their scales are armor-grade, their blood is fuel. Monopolize the supply.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 24, "reputation_required": 1380, "required_quests": ["fq_merid_024"]}'::jsonb, '[{"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "desc": "Monopolize the Leviathan supply.", "description": "Defeat Sunken Aethel Leviathan (x1)."}, {"type": "collect", "target": "leviathan_scale", "count": 1, "desc": "Submit commodity valuation report.", "description": "Collect leviathan scale (x1). [Item: Leviathan Scale]"}]'::jsonb, '{"exp": 1000, "currency": 550, "crd": 165, "rep": 550, "items": [{"item_id": "ancient_scale", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_merid_026', false, NULL, NULL, NULL, 'quest_meridian.json', 24)
