values ('fq_merid_026', 'Storm Belt Futures', 'exploration', 'B', 'MERIDIAN_CARTEL', 'AETHEL_STORM_BELT', 'The Aethel Storm Belt is a high-risk, high-reward market. The Cartel is opening a trading desk there. Establish the position. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 25, "reputation_required": 1440, "required_quests": ["fq_merid_025"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_STORM_BELT", "count": 1, "desc": "Enter the Aethel Storm Belt.", "description": "Travel to AETHEL STORM BELT. (Travel to: Aethel Storm Belt)"}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Gather market intelligence.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_merid_027', false, NULL, NULL, NULL, 'quest_meridian.json', 25)
