values ('fq_merid_027', 'Storm Serpent Commodity', 'hunt', 'B', 'MERIDIAN_CARTEL', 'AETHEL_STORM_BELT', 'Storm Rift Serpents are a volatile commodity. (Location: Aethel Storm Belt, Don Vercelli) Their energy cells are in high demand. Stabilize the supply.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 26, "reputation_required": 1500, "required_quests": ["fq_merid_026"]}'::jsonb, '[{"type": "kill", "target": "STORM_RIFT_SERPENT", "count": 3, "desc": "Stabilize Serpent commodity supply.", "description": "Defeat Storm Rift Serpent (x3)."}, {"type": "collect", "target": "storm_core", "count": 2, "desc": "Collect energy cells for market.", "description": "Collect storm core (x2). [Item: Storm Core]"}]'::jsonb, '{"exp": 750, "currency": 430, "crd": 129, "rep": 430, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_merid_028', false, NULL, NULL, NULL, 'quest_meridian.json', 26)
