values ('fq_merid_028', 'Leviathan Market', 'boss', 'B', 'MERIDIAN_CARTEL', 'AETHEL_STORM_BELT', 'Leviathans have migrated into the Storm Belt. (Location: Aethel Storm Belt, Kip) More supply means more profit. Harvest aggressively.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 27, "reputation_required": 1560, "required_quests": ["fq_merid_027"]}'::jsonb, '[{"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 2, "desc": "Harvest Leviathan supply.", "description": "Defeat Sunken Aethel Leviathan (x2)."}, {"type": "collect", "target": "slime_core", "count": 1, "desc": "File harvest yield report.", "description": "Collect slime core (x1). [Item: Slime Core]"}]'::jsonb, '{"exp": 900, "currency": 520, "crd": 156, "rep": 520, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_merid_029', false, NULL, NULL, NULL, 'quest_meridian.json', 27)
