values ('fq_merid_029', 'Sentinel Acquisition', 'boss', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Cradle Sentinel variants have been discovered. (Location: Sunken Aethel Ruin, Don Vercelli) More variety means more market segmentation. Acquire samples of all models.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SUNKEN_AETHEL_RUIN"}'::jsonb, '{"min_level": 28, "reputation_required": 1620, "required_quests": ["fq_merid_028"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_SENTINEL", "count": 4, "desc": "Acquire all Sentinel model samples.", "description": "Defeat Cradle Sentinel (x4)."}, {"type": "collect", "target": "aethel_core_shard", "count": 1, "desc": "Complete the Sentinel variant catalog.", "description": "Collect aethel core shard (x1). [Item: Aethel Core Shard]"}]'::jsonb, '{"exp": 850, "currency": 480, "crd": 144, "rep": 480, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_merid_030', false, NULL, NULL, NULL, 'quest_meridian.json', 28)
