values ('fq_merid_030', 'The Second Audit', 'story', 'B', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'Captain Vex requires a mid-contract performance review. (Location: Port Meridian, Captain Vex) Defeat the Resonance Echo and prove your portfolio is Master-grade.', '{"npc_id": "npc_meridian_class_trainer", "name": "Captain Vex", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 29, "reputation_required": 95, "required_quests": ["fq_merid_029"]}'::jsonb, '[{"type": "interact", "target": "npc_meridian_class_trainer", "count": 1, "desc": "Present your portfolio to Captain Vex.", "description": "Speak with npc meridian class trainer. (Captain Vex at Port Meridian Covert Training Facility)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "desc": "Demonstrate ROI against the Resonance Echo.", "description": "Defeat Resonance Echo (x1)."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "desc": "Harvest a Behemoth as your closing transaction.", "description": "Defeat Aethel Behemoth (x1)."}]'::jsonb, '{"exp": 2500, "currency": 1200, "crd": 360, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}, {"item_id": "astral_phase_crystal_pure", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_merid_031', true, 'on_quest_complete', 29, 'fq_merid_029', 'quest_meridian.json', 29)
