values ('fq_merid_031', 'Orbital Monopoly', 'exploration', 'A', 'MERIDIAN_CARTEL', 'ORBITAL_SENTINEL_COMMAND', 'The Orbital Sentinel Command is the gateway to space trade. The Cartel will establish exclusive orbital trading rights. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 1740, "required_quests": ["fq_merid_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "desc": "Report to Orbital Sentinel Command.", "description": "Travel to ORBITAL SENTINEL COMMAND. (Travel to: Orbital Sentinel Command)"}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Secure the orbital trade license.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 250, "rep": 500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_merid_032', false, NULL, NULL, NULL, 'quest_meridian.json', 30)
