values ('fq_merid_032', 'Drake Insurance', 'hunt', 'A', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'The Ashen Drake attacks Cartel cargo ships. (Location: Cradle Expanse, Don Vercelli) The insurance premiums are killing profits. Eliminate the risk factor.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 1800, "required_quests": ["fq_merid_031"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Eliminate the Drake risk factor.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "ancient_scale", "count": 1, "desc": "File reduced cargo loss report.", "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 1200, "currency": 650, "crd": 325, "rep": 650, "items": [{"item_id": "drake_heart", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_merid_033', false, NULL, NULL, NULL, 'quest_meridian.json', 31)
