values ('fq_merid_033', 'Carapace Commodity', 'hunt', 'A', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'Aethel Iron Carapaces shed armor plates that rival Cartel-forged steel. (Location: Cradle Expanse, Don Vercelli) Corner the market.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 1860, "required_quests": ["fq_merid_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 6, "desc": "Corner the Carapace armor market.", "description": "Defeat Aethel Iron Carapace (x6)."}, {"type": "collect", "target": "carapace_fragment", "count": 3, "desc": "Prepare armor plate shipments.", "description": "Collect carapace fragment (x3). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 1400, "currency": 750, "crd": 375, "rep": 750, "items": [{"item_id": "rusted_plate", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_merid_034', false, NULL, NULL, NULL, 'quest_meridian.json', 32)
