values ('fq_merid_038', 'Market Dominance', 'hunt', 'A', 'MERIDIAN_CARTEL', 'AETHEL_STORM_BELT', 'Achieve total market dominance in the Storm Belt. (Location: Aethel Storm Belt, Don Vercelli) Any competitor still operating is a market inefficiency.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 37, "reputation_required": 2160, "required_quests": ["fq_merid_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Eliminate market inefficiencies.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "alpha_fang", "count": 1, "desc": "File market dominance confirmation.", "description": "Collect alpha fang (x1). [Item: Alpha Fang]"}]'::jsonb, '{"exp": 1700, "currency": 900, "crd": 450, "rep": 900, "items": [{"item_id": "scrap_metal", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_merid_039', false, NULL, NULL, NULL, 'quest_meridian.json', 37)
