values ('fq_merid_039', 'Abyssal Merger', 'boss', 'A', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'Abyssal Reavers are attempting a merger — with each other — to form a larger threat. (Location: Cradle Expanse, Don Vercelli) Block the merger.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 2220, "required_quests": ["fq_merid_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Block the Abyssal merger.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Eliminate merger facilitators.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 2000, "currency": 1100, "crd": 550, "rep": 1100, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_merid_040', false, NULL, NULL, NULL, 'quest_meridian.json', 38)
