values ('fq_merid_040', 'Senior Partner', 'story', 'A', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'The Senior Partner trial. (Location: Port Meridian, Don Vercelli) Liquidate the Ashen Drake and two premium assets. Only Partners sit on the Cartel board.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 39, "reputation_required": 105, "required_quests": ["fq_merid_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Complete the Drake liquidation.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "desc": "Harvest a premium Behemoth asset.", "description": "Defeat Aethel Behemoth (x1)."}, {"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "desc": "Acquire a premium Leviathan asset.", "description": "Defeat Sunken Aethel Leviathan (x1)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "ancient_scale", "quantity": 2}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_merid_041', false, NULL, NULL, NULL, 'quest_meridian.json', 39)
