values ('fq_merid_041', 'Black Market Deep Dive', 'exploration', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'The Void Echo Chasm is the ultimate untapped market. Rare minerals, void-exclusive resources, zero competition. The Cartel is going in. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 2340, "required_quests": ["fq_merid_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Enter the Void Echo Chasm.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "collect", "target": "thick_hide", "count": 2, "desc": "Complete void market survey.", "description": "Collect thick hide (x2). [Item: Thick Hide]"}]'::jsonb, '{"exp": 1800, "currency": 900, "crd": 450, "rep": 600, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_042', false, NULL, NULL, NULL, 'quest_meridian.json', 40)
