values ('fq_merid_042', 'Reaver Commodity', 'hunt', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Void Reavers drop crystallized void essence — untapped market value. (Location: Void Echo Chasm, Don Vercelli) Begin harvesting operations.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 2400, "required_quests": ["fq_merid_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Harvest Reaver void essence commodity.", "description": "Defeat Void Reaver (x6)."}, {"type": "collect", "target": "void_fragment", "count": 1, "desc": "Prepare first void essence shipment.", "description": "Collect void fragment (x1). [Item: Void Fragment]"}]'::jsonb, '{"exp": 1900, "currency": 950, "crd": 475, "rep": 650, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_043', false, NULL, NULL, NULL, 'quest_meridian.json', 41)
