values ('fq_merid_043', 'Channeler Competition', 'story', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Void Channelers are cornering the void energy market. (Location: Void Echo Chasm, Don Vercelli) The Cartel does not tolerate monopolies — except its own.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 130, "required_quests": ["fq_merid_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Break the Channeler void monopoly.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Claim their market share.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 700, "items": [{"item_id": "event_horizon_fragment", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_044', false, NULL, NULL, NULL, 'quest_meridian.json', 42)
